// Pin and trim the timezone data to the supported birth range with a year's margin.
const fs = require('node:fs')
const mt = require('moment-timezone/moment-timezone-utils')
const packed = require('moment-timezone/data/packed/latest.json')
const filtered = mt.tz.filterLinkPack(
  { version: packed.version, zones: packed.zones.map(mt.tz.unpack), links: packed.links },
  1899,
  2101
)
fs.writeFileSync(
  'src/lib/zones-data.js',
  '// Generated by scripts/pack-zones.cjs\nexport default ' + JSON.stringify(filtered) + '\n'
)
